// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

/** The full HR profile: qualifications, documents, contract, login, badges, schedule and submit checklist. */
export interface EmployeeDetailOut {
  employee_id: number;
  emp_number: string;
  full_name: string;
  father_or_husband_name: string | null;
  cnic: string;
  dob: string | null;
  gender: "male" | "female" | "other" | "unknown" | null;
  mobile: string;
  email: string | null;
  address: string | null;
  blood_group: "A+" | "A-" | "B+" | "B-" | "AB+" | "AB-" | "O+" | "O-" | "Unknown" | null;
  department_id: number | null;
  department_name: string | null;
  designation: string;
  specialty: string | null;
  supervisor_id: number | null;
  supervisor_name: string | null;
  base_salary: number;
  contract_type: "Permanent" | "Contract" | "Visiting";
  employment_status: "Draft" | "Awaiting_IT_Provisioning" | "Active" | "Suspended" | "Resigned" | "Terminated";
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting";
  is_clinical_staff: boolean;
  license_type: "PMDC" | "PNC" | "Other" | null;
  license_number: string | null;
  joined_on: string | null;
  left_on: string | null;
  /** The wizard step to continue at (1-6) */
  onboarding_step: number;
  row_version: number;
  created_at: string;
  qualifications: QualificationOut[];
  /** The commission contract in force today */
  contract: ContractOut | null;
  /** The active login (created by IT after provisioning) */
  user: EmployeeLoginOut | null;
  badges: EmployeeBadgeOut[];
  schedule: EmployeeScheduleOut;
  checklist: SubmitChecklistOut;
  documents: EmployeeDocumentOut[];
}

export interface QualificationOut {
  qualification_id: number;
  employee_id: number;
  qualification_type: "Education" | "Experience" | "License" | "Certification";
  title: string;
  institution: string | null;
  year: number | null;
  license_number: string | null;
  license_expiry: string | null;
  notes: string | null;
  /** Verified with the primary source (the HEC, the university, the PMDC/PNC): MSDS HRM 142 */
  verification_status: "Pending" | "Verified" | "Failed" | "NotRequired";
  verified_with: string | null;
  verification_ref: string | null;
  verified_on: string | null;
  row_version: number;
}

/** A consultant's commission rule (workflow section 5.5). */
export interface ContractOut {
  contract_id: number;
  employee_id: number;
  rule_type: "FixedFee" | "PercentGross" | "PercentNet";
  terms_jsonb: Record<string, unknown>;
  effective_from: string;
  effective_to: string | null;
  notes: string | null;
  decided_by: number | null;
  decided_at: string;
  row_version: number;
}

export interface EmployeeLoginOut {
  user_id: number;
  username: string;
  is_active: boolean;
}

export interface EmployeeBadgeOut {
  badge_code: string;
  technology: "RFID" | "Barcode" | "Biometric";
  holder_type: "Employee" | "SupportStaff" | "Sweeper" | "Janitor" | "Security" | "Contractor";
  label: string | null;
  issued_at: string;
}

/** Today's default shift and its weekly days off; shift_pattern_id null = works to the duty roster only (rest days are the days without a duty, rotating through the week). */
export interface EmployeeScheduleOut {
  shift_pattern_id: number | null;
  shift_name: string | null;
  effective_from: string | null;
  /** ISO weekdays (1 = Monday … 7 = Sunday); [] for roster-only staff */
  weekly_off_days: number[];
}

export interface SubmitChecklistOut {
  ready: boolean;
  /** What still blocks submission, e.g. "CNIC document" */
  missing: string[];
}

export interface EmployeeDocumentOut {
  document_id: number;
  doc_type: "CNIC" | "Degree" | "PMDC" | "PNC" | "Experience" | "Contract" | "Photo" | "Other";
  title: string | null;
  content_type: "application/pdf" | "image/jpeg" | "image/png";
  size_bytes: number | null;
  is_required: boolean;
  is_verified: boolean;
  uploaded_at: string;
}

export interface BadgeIn {
  /** Barcode = a QR badge printed on the ID card (no RFID hardware needed); the server generates its code */
  technology?: "RFID" | "Barcode" | "Biometric";
  /** RFID: the card UID the reader reports. Biometric: the enrolment id. Barcode: leave empty */
  badge_code?: string | null;
  holder_type?: "Employee" | "SupportStaff" | "Sweeper" | "Janitor" | "Security" | "Contractor";
  label?: string | null;
}

export interface IssuedBadgeOut {
  badge_code: string;
  technology: "RFID" | "Barcode" | "Biometric";
  employee_id: number | null;
  holder_type: "Employee" | "SupportStaff" | "Sweeper" | "Janitor" | "Security" | "Contractor";
  label: string | null;
  is_active: boolean;
  issued_at: string;
  revoked_at: string | null;
  revoke_reason: string | null;
  row_version: number;
  /** Printed (Barcode) badges only */
  qr_svg?: string | null;
  /** Printed (Barcode) badges only */
  barcode_svg?: string | null;
}

export interface HrReasonIn {
  reason: string;
}

export interface StaffBadgeOut {
  badge_code: string;
  technology: "RFID" | "Barcode" | "Biometric";
  employee_id: number | null;
  holder_type: "Employee" | "SupportStaff" | "Sweeper" | "Janitor" | "Security" | "Contractor";
  label: string | null;
  is_active: boolean;
  issued_at: string;
  revoked_at: string | null;
  revoke_reason: string | null;
  row_version: number;
}

/** Data for the ID card designer; the frontend renders and prints it on the card printer. */
export interface IdCardOut {
  document_type: "autopsy_order" | "bed_labels" | "blood_component_label" | "blood_donation_labels" | "clinical_note" | "complaint_letter" | "complaints_notice" | "consent_form" | "cost_estimate" | "cssd_labels" | "death_certificate" | "discharge_summary" | "dispensing_label" | "dose_label" | "id_card" | "imaging_report" | "lab_label" | "lab_report" | "mlc_intimation" | "opd_slip" | "pharmacy_receipt" | "prescription" | "referral_slip" | "send_out_manifest" | "surgical_record" | "triage_algorithm" | "wristband";
  printer_role: "receipt" | "label" | "document" | "card";
  card_size_mm: number[];
  fields: IdCardFieldsOut;
  barcode_svg: string;
  qr_svg: string;
  /** The printed staff badge for barcode stations, if one is issued */
  badge: PrintedBadgeOut | null;
}

export interface IdCardFieldsOut {
  hospital_name: string;
  full_name: string;
  designation: string;
  department: string | null;
  emp_number: string;
  blood_group: "A+" | "A-" | "B+" | "B-" | "AB+" | "AB-" | "O+" | "O-" | "Unknown" | null;
  joined_on: string | null;
  license: string | null;
  photo_document_id: number | null;
}

export interface PrintedBadgeOut {
  badge_code: string;
  qr_svg: string;
  barcode_svg: string;
}

/** Full profile incl. documents, qualifications, submit checklist — GET /api/v1/hr/employees/{employee_id} (who may call: holders of hr.employee.view). */
export function getHrEmployees(employee_id: number): Promise<EmployeeDetailOut> {
  return api<EmployeeDetailOut>("GET", `/hr/employees/${employee_id}`, undefined);
}

/** Issue a staff badge: RFID card, printed QR badge or biometric enrolment — POST /api/v1/hr/employees/{employee_id}/badges (who may call: holders of hr.badge.manage). */
export function issueBadge(employee_id: number, body: BadgeIn): Promise<IssuedBadgeOut> {
  return api<IssuedBadgeOut>("POST", `/hr/employees/${employee_id}/badges`, body, { idempotent: true });
}

/** Revoke a lost / returned badge — POST /api/v1/hr/badges/{badge_code}/revoke (who may call: holders of hr.badge.manage). */
export function revokeBadge(badge_code: string, body: HrReasonIn): Promise<StaffBadgeOut> {
  return api<StaffBadgeOut>("POST", `/hr/badges/${badge_code}/revoke`, body);
}

/** ID card designer payload (barcode + QR of the EMP number) — GET /api/v1/hr/employees/{employee_id}/id-card (who may call: holders of hr.idcard.print). */
export function idCard(employee_id: number): Promise<IdCardOut> {
  return api<IdCardOut>("GET", `/hr/employees/${employee_id}/id-card`, undefined);
}
